fn validate_user_input(username: Str, age: Int) -> Int
  requires: username.len() > 0;
  requires: username.len() <= 50;
  requires: age >= 0;
  requires: age <= 150;
{
  io.println("User: " + username + ", Age: " + age.to_str());
  return age;
}

fn main() -> Int {
  // Input validation should always be runtime-checked — attackers don't respect contracts.
  return validate_user_input("Alice", 30);
}
